SEXP = [
    ('eqb_bads_10', ['Fz', 'O1', '|', 'Fz', 'O1']),
    ('eqb_bads_0', ['|']),
    ('eqb_bads_6', ['Fz', '|', 'Fz']),
]


def _fget(name: str) -> List[float]:
    for n, v in FEXP:
        if n == name:
            return v
    raise ValueError("missing " + name)


def _sget(name: str) -> List[str]:
    for n, v in SEXP:
        if n == name:
            return v
    raise ValueError("missing " + name)


def _flat(got) -> List[float]:
    g = List[float]()
    a = np.asarray(got, dtype=float).ravel()
    for i in range(a.shape[0]):
        g.append(float(a[i]))
    return g


def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-15):
    want = _fget(name)
    g = _flat(got)
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if np.isnan(want[i]):
                if not np.isnan(g[i]):
                    ok = False
            elif abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g[:12], want[:12], len(g), len(want))


def checks(name: str, got):
    want = _sget(name)
    g = [str(v) for v in got]
    if g != want:
        print("TEST FAILED:", name, g, want)



def V(x):
    return x.__val__()


def TS(x):
    return x.__val__()


def mk(nch: int, n: int, k: float):
    out = np.empty((nch, n))
    for i in range(nch):
        for j in range(n):
            out[i, j] = np.sin(0.05 * (i + 1) * j + k) + 0.3 * np.cos(0.31 * j * (i + 2) + 0.5 * i) + 0.2 * np.sin(2.0 * j)
    return out


names = ['Fp1', 'Fz', 'Cz', 'Pz', 'O1', 'O2']
sf = 100.0
data = mk(6, 1500, 0.3) * 1e-5
raw = mne.io.RawArray(data, mne.create_info(names, sf, 'eeg'))
ev = np.array([[100, 0, 1], [400, 0, 2], [700, 0, 1]])
for md in ['linear', 'window', 'constant']:
    r = raw.copy()
    mne.preprocessing.fix_stim_artifact(r, events=ev, event_id=1, tmin=-0.02, tmax=0.1, mode=md, baseline=(-0.1, -0.05))
    check("fsa_raw_" + md, r.get_data()[:, 95:115], 1e-9, 1e-15)
ep = mne.Epochs(raw, ev, tmin=-0.2, tmax=0.5, baseline=None, preload=True)
for md in ['linear', 'window', 'constant']:
    e2 = ep.copy()
    mne.preprocessing.fix_stim_artifact(e2, tmin=0.0, tmax=0.05, mode=md, baseline=(-0.1, -0.05))
    check("fsa_ep_" + md, e2.get_data()[1, :, 15:30], 1e-9, 1e-15)
evk = ep.average()
mne.preprocessing.fix_stim_artifact(evk, tmin=0.0, tmax=0.05)
check("fsa_evk", evk.data[:, 15:30], 1e-9, 1e-15)

# annotate_nan
d2 = data.copy()
d2[1, 200:230] = np.nan
d2[3, 900:905] = np.nan
d2[3, 1000:1010] = np.nan
r2 = mne.io.RawArray(d2, mne.create_info(names, sf, 'eeg'))
an = mne.preprocessing.annotate_nan(r2)
check("nan_on", an.onset)
check("nan_du", an.duration)

# equalize_bads
mon = mne.channels.make_standard_montage('standard_1020')
ra = mne.io.RawArray(data, mne.create_info(names, sf, 'eeg'))
rb = mne.io.RawArray(mk(6, 800, 0.9) * 1e-5, mne.create_info(names, sf, 'eeg'))
ra.set_montage(mon)
rb.set_montage(mon)
ra.info['bads'] = ['Fz']
rb.info['bads'] = ['Fz', 'O1']
for th in [1.0, 0.0, 0.6]:
    o = mne.preprocessing.equalize_bads([ra, rb], interp_thresh=th)
    checks("eqb_bads_%d" % int(th * 10), o[0].info['bads'] + ['|'] + o[1].info['bads'])
    check("eqb_d0_%d" % int(th * 10), o[0].get_data()[:, 50:52], 1e-6, 1e-12)
    check("eqb_d1_%d" % int(th * 10), o[1].get_data()[:, 50:52], 1e-6, 1e-12)

# bridged electrodes
d3 = mk(6, 1500, 0.3) * 1e-5
d3[3] = d3[2] + 1e-8 * mk(1, 1500, 2.0)[0]
r3 = mne.io.RawArray(d3, mne.create_info(names, sf, 'eeg'))
br, ed = mne.preprocessing.compute_bridged_electrodes(r3)
check("br_pairs", np.array(br, dtype=float).reshape(-1))
check("br_ed", ed[0:2].reshape(-1)[:40], 1e-6, 1e-12)
